from pathlib import Path
import re

replacements = {
    'ray_processing/process.py': [
        (re.compile(rb'(os\.environ\["AWS_ACCESS_KEY_ID"\]\s*=\s*")[^"]+(")'), rb'\1<your-aws-access-key-id>\2'),
    ],
    'ray_processing/ray_cluster.yaml': [
        (re.compile(rb'(AWS_ACCESS_KEY_ID=)[^\'\s]+'), rb'\1<your-aws-access-key-id>'),
        (re.compile(rb'(AWS_SECRET_ACCESS_KEY=)[^\'\s]+'), rb'\1<your-aws-secret-access-key>'),
        (re.compile(rb'(https://)[^@/\s]+(@github\.com/)'), rb'\1<your-github-token>\2'),
        (re.compile(rb'(--token\s+)[^\s\'\"]+'), rb'\1<your-huggingface-token>'),
    ],
    'exp_data/datasets/tokenized/rw_v2_fasttext_openhermes_vs_rw_v2_bigram_0.1_arcade100k.json': [
        (re.compile(rb'\bhf_[A-Za-z0-9]{20,}\b'), rb'<your-huggingface-token>'),
    ],
}

for filename, rules in replacements.items():
    path = Path(filename)
    data = path.read_bytes()
    original = data
    for pattern, replacement in rules:
        data, count = pattern.subn(replacement, data)
        if count != 1:
            raise RuntimeError(f'{filename}: expected exactly one replacement, got {count}')
    if data == original:
        raise RuntimeError(f'{filename}: no content changed')
    path.write_bytes(data)
    print(f'sanitized {filename}')
